-- Fresh D1 identity schema (#604). Dates are integer Unix milliseconds.
-- JSON and scalar arrays are JSON TEXT; booleans are INTEGER 0/1.
-- IDs are generated by the application, never copied from the retired database.
-- Remaining domain tables and food-source continuity triggers follow separately.
PRAGMA foreign_keys = ON;

CREATE TABLE "Family" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "name" TEXT NOT NULL,
  "invite_code" TEXT NOT NULL UNIQUE,
  "subscription_tier" TEXT NOT NULL DEFAULT 'free',
  "features" TEXT DEFAULT '{"chores":true,"calendar":true,"lists":true,"family":true,"meals":true,"notes":false,"anniversaries":false,"rewards":false,"budget":false,"projects":false,"messages":false,"analytics":false,"wishlist":false,"emergency":true,"locations":false,"pickups":false,"allowance":false,"travel":false,"handoff":false,"sick-days":false,"gamification":false,"inventory":false}' CHECK ("features" IS NULL OR json_valid("features")),
  "display_defaults" TEXT CHECK ("display_defaults" IS NULL OR json_valid("display_defaults")),
  "display_defaults_revision" INTEGER NOT NULL DEFAULT 0,
  "travel_mode_active" INTEGER NOT NULL DEFAULT 0 CHECK ("travel_mode_active" IN (0, 1)),
  "travel_start_date" INTEGER,
  "travel_end_date" INTEGER,
  "travel_destination" TEXT,
  "feed_token" TEXT UNIQUE,
  "capture_ai_key_enc" TEXT,
  "capture_ai_base_url" TEXT,
  "capture_ai_model" TEXT,
  "weather_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("weather_enabled" IN (0, 1)),
  "weather_latitude" REAL,
  "weather_longitude" REAL,
  "weather_label" TEXT,
  "weather_unit" TEXT NOT NULL DEFAULT 'celsius',
  "ambient_idle_minutes" INTEGER NOT NULL DEFAULT 5,
  "night_start" TEXT,
  "night_end" TEXT,
  "ambient_photo_ids" TEXT NOT NULL DEFAULT '[]' CHECK ("ambient_photo_ids" IS NULL OR json_valid("ambient_photo_ids")),
  "device_writes_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("device_writes_enabled" IN (0, 1)),
  "beta_metrics_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("beta_metrics_enabled" IN (0, 1)),
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER))
);

CREATE TABLE "User" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "email" TEXT NOT NULL UNIQUE,
  "password" TEXT,
  "name" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'parent',
  "age" INTEGER,
  "family_id" TEXT,
  "avatar_url" TEXT,
  "last_chore_date" INTEGER,
  "xp" INTEGER NOT NULL DEFAULT 0,
  "level" INTEGER NOT NULL DEFAULT 1,
  "streak" INTEGER NOT NULL DEFAULT 0,
  "best_streak" INTEGER NOT NULL DEFAULT 0,
  "email_verified" INTEGER NOT NULL DEFAULT 0 CHECK ("email_verified" IN (0, 1)),
  "reset_token" TEXT,
  "reset_token_expires" INTEGER,
  "verify_token" TEXT,
  "verify_token_expires" INTEGER,
  "token_version" INTEGER NOT NULL DEFAULT 0,
  "board_color" TEXT,
  "display_preferences" TEXT CHECK ("display_preferences" IS NULL OR json_valid("display_preferences")),
  "display_preferences_revision" INTEGER NOT NULL DEFAULT 0,
  "weekly_reset_progress" TEXT CHECK ("weekly_reset_progress" IS NULL OR json_valid("weekly_reset_progress")),
  "weekly_reset_revision" INTEGER NOT NULL DEFAULT 0,
  "notify_chores" INTEGER NOT NULL DEFAULT 1 CHECK ("notify_chores" IN (0, 1)),
  "notify_events" INTEGER NOT NULL DEFAULT 1 CHECK ("notify_events" IN (0, 1)),
  "notify_messages" INTEGER NOT NULL DEFAULT 1 CHECK ("notify_messages" IN (0, 1)),
  "quiet_hours_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("quiet_hours_enabled" IN (0, 1)),
  "quiet_hours_start" TEXT NOT NULL DEFAULT '22:00',
  "quiet_hours_end" TEXT NOT NULL DEFAULT '07:00',
  "quiet_hours_time_zone" TEXT,
  "morning_summary_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("morning_summary_enabled" IN (0, 1)),
  "morning_summary_time_zone" TEXT,
  "morning_summary_sent_on" TEXT,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  FOREIGN KEY ("family_id") REFERENCES "Family"("id") ON DELETE SET NULL,
  UNIQUE ("id", "family_id")
);

CREATE TABLE "FamilyInvite" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "family_id" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "role" TEXT NOT NULL,
  "token_hash" TEXT NOT NULL UNIQUE,
  "expires_at" INTEGER NOT NULL,
  "accepted_at" INTEGER,
  "created_by" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  FOREIGN KEY ("family_id") REFERENCES "Family"("id") ON DELETE CASCADE,
  FOREIGN KEY ("created_by") REFERENCES "User"("id") ON DELETE CASCADE
);

CREATE TABLE "RateLimitEntry" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "key" TEXT NOT NULL UNIQUE,
  "count" INTEGER NOT NULL DEFAULT 1,
  "windowStart" INTEGER NOT NULL,
  "resetAt" INTEGER NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  "updated_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER))
);

CREATE TABLE "AuditLog" (
  "id" TEXT PRIMARY KEY NOT NULL,
  "family_id" TEXT NOT NULL,
  "actor_user_id" TEXT,
  "actor_kind" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "target_type" TEXT NOT NULL,
  "target_id" TEXT,
  "summary" TEXT NOT NULL,
  "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000 AS INTEGER)),
  FOREIGN KEY ("family_id") REFERENCES "Family"("id") ON DELETE CASCADE,
  FOREIGN KEY ("actor_user_id") REFERENCES "User"("id") ON DELETE SET NULL
);

CREATE INDEX "User_family_id_idx" ON "User"("family_id");
CREATE INDEX "User_reset_token_idx" ON "User"("reset_token");
CREATE INDEX "FamilyInvite_family_id_email_idx" ON "FamilyInvite"("family_id", "email");
CREATE INDEX "FamilyInvite_expires_at_idx" ON "FamilyInvite"("expires_at");
CREATE INDEX "RateLimitEntry_resetAt_idx" ON "RateLimitEntry"("resetAt");
CREATE INDEX "AuditLog_family_id_created_at_idx" ON "AuditLog"("family_id", "created_at");
